      "hanVietRead": "Càn, nguyên hanh lợi trinh. Tượng viết: Thiên hành kiện, quân tử dĩ tự cường bất tức. Tiềm long vật dụng, dương tại hạ dã. Hiện long tại điền, đức thí phổ dã. Phi long tại thiên, đại nhân tạo dã.",
      "translationVi": "Quẻ Càn mang bốn đặc tính khởi nguyên, hanh thông, hài hòa và bền vững. Lời Tượng khẳng định bầu trời vận chuyển mạnh mẽ liên tục, người quân tử dựa vào quy luật ấy để tự rèn luyện ý chí không ngơi nghỉ. Rồng ẩn sâu chưa nên hành động vì dương khí còn ở vị thế thấp. Rồng xuất hiện ngoài đồng cho thấy ân đức bắt đầu lan tỏa rộng khắp. Rồng bay giữa tầng không tượng trưng cho bậc đại nhân lập nên sự nghiệp lớn. Văn bản này đặt cơ sở cho vũ trụ quan vận động liên tục và tinh thần nhập thế chủ động của Nho học.",
