      "hanVietRead": "Nhất âm nhất dương chi vị đạo, kế chi giả thiện dã, thành chi giả tính dã. Nhân giả kiến chi vị chi nhân, trí giả kiến chi vị chi trí. Sinh sinh chi vị dịch, thành tượng chi vị càn, hiệu pháp chi vị khôn.",
      "translationVi": "Sự luân chuyển qua lại giữa một mặt âm và một mặt dương được gọi là Đạo; tiến trình nối tiếp quy luật ấy tạo nên điều thiện; sự kết tinh trong mỗi sinh thể tạo thành bản tính. Người giàu lòng nhân nhìn thấy Đạo rồi gọi đó là nhân, người giàu trí tuệ nhìn thấy Đạo rồi gọi đó là trí. Quá trình sinh thành nối tiếp bất tận gọi là Dịch; bước định hình biểu tượng ban đầu là Càn; bước mô phỏng nuôi dưỡng cho thành vật thể là Khôn. Đoạn luận thuyết này chuyển hóa kinh bói toán cổ thành hệ thống triết học về biến dịch.",
      "translationEn": "The rhythmic alternation of yin and yang defines the Way; carrying that process forward constitutes goodness, while its realization within individual beings forms innate nature. Compassionate observers perceive this pattern as benevolence, whereas analytical minds interpret it as wisdom. Perpetual regeneration is termed Change: Qian initiates formative archetypes, and Kun emulates and nurtures them into tangible existence. This philosophical commentary transforms archaic divination into a systematic metaphysics of continuous renewal.",
