      "translationVi": "Hạng mục đầu tiên là Ngũ hành; thứ hai là thận trọng thực hành Ngũ sự trong thái độ và ngôn hạnh; thứ ba là chuyên cần điều hành Bát chính lo đời sống dân sinh; thứ tư là phối hợp Ngũ kỷ lịch pháp thiên văn; thứ năm là thiết lập chuẩn mực Hoàng cực trung chính của bậc quân vương. Hệ thống Ngũ hành gồm năm yếu tố vận động cơ bản là Thủy, Hỏa, Mộc, Kim và Thổ. Thiên Hồng Phạm là văn bản cổ sớm nhất gắn kết mô hình vũ trụ Ngũ hành với khuôn khổ trị quốc.",
      "translationEn": "The first category establishes the Five Phases; the second mandates disciplined conduct in the Five Personal Affairs; the third prioritizes diligent administration of the Eight Policies; the fourth coordinates the Five Astronomical Timekeepers; and the fifth erects the Sovereign Standard of balanced rule. The Five Phases comprise Water, Fire, Wood, Metal, and Earth. The Great Plan stands as the earliest surviving treatise integrating Five Phases natural philosophy directly into an institutional blueprint for governance.",
