      "vietnamReceptionVi": "Hình ảnh Thất nguyệt lưu Hỏa và cảnh nông tang bốn mùa trong Bân Phong thường được triều đình Lý, Trần, Lê và Nguyễn dẫn lại trong lễ Tịch điền khuyến nông. Nhiều thi nhân Việt Nam như Nguyễn Trãi hay Nguyễn Khuyến cũng tiếp thu cảm hứng nông lịch này khi sáng tác thơ điền viên.",
      "vietnamReceptionEn": "The seasonal imagery of Seventh Month was regularly invoked by Ly, Tran, Le, and Nguyen courts during royal plowing rituals promoting agriculture. Vietnamese poets including Nguyen Trai and Nguyen Khuyen drew upon its agrarian rhythms when composing rural countryside verse."
