      "vietnamReceptionVi": "Luận Ngữ là kinh điển nền tảng tại Văn Miếu – Quốc Tử Giám từ năm 1070 và xuyên suốt lịch sử khoa cử Đại Việt. Tinh thần Vi chính dĩ đức thường xuất hiện trong chiếu chỉ của các vua Lê Thánh Tông, Minh Mạng, còn phương châm Khắc kỷ phục lễ trở thành khuôn vàng thước ngọc rèn luyện nhân cách kẻ sĩ.",
      "vietnamReceptionEn": "The Analects anchored instruction at the Temple of Literature and Imperial Academy in Hanoi from 1070 onward. Rulers like Le Thanh Tong and Minh Mang echoed virtue-based governance in royal edicts, while self-mastery and ritual propriety formed the bedrock of Vietnamese scholar-official ethics."
