      "vietnamReceptionVi": "Mệnh đề Đạo sinh nhất, vạn vật phụ âm nhi bão dương có ảnh hưởng sâu sắc đến y học cổ truyền và dưỡng sinh Việt Nam, tiêu biểu qua tác phẩm của Tuệ Tĩnh và Hải Thượng Lãn Ông. Đồng thời, triết lý tổn ích tuần hoàn cũng đi vào tư tưởng ứng xử khiêm cung của giới trí thức truyền thống.",
      "vietnamReceptionEn": "The cosmogonic sequence of unity branching into yin, yang, and harmonizing breath shaped traditional Vietnamese medicine and longevity practices, notably in the works of Tue Tinh and Hai Thuong Lan Ong. Its dialectic of gain and loss also guided traditional ideals of modest conduct."
