      "vietnamReceptionVi": "Những câu cách ngôn như Học bất khả dĩ dĩ và Thanh xuất ư lam sớm trở thành lời răn quen thuộc trong các gia huấn và trường học truyền thống Việt Nam. Tinh thần tích tiểu thành đại của Tuân Tử tương thông sâu sắc với tục ngữ Kiến tha lâu cũng đầy tổ và truyền thống hiếu học qua nhiều thế hệ.",
      "vietnamReceptionEn": "Maxims from Encouraging Learning, especially the indigo-surpassing-the-plant metaphor and lifelong study, became staples of Vietnamese family precepts and village schools. Xunzi's emphasis on steady accumulation harmonized closely with Vietnamese proverbs on persistence and multigenerational devotion to scholarship."
