      "vietnamReceptionVi": "Tứ diện Sở ca và khúc Cai Hạ ca trở thành điển cố quen thuộc trong văn học và kịch hát bội (tuồng) cổ truyền Việt Nam, tiêu biểu qua vở tuồng Hạng Võ biệt Ngu Cơ. Các sử gia từ Lê Văn Hưu đến Ngô Sĩ Liên cũng học tập bút pháp phân tích nhân vật đa chiều của Tư Mã Thiên khi luận bàn thành bại anh hùng.",
      "vietnamReceptionEn": "The Songs of Chu on Four Sides and the Gaixia lament became enduring motifs in Vietnamese literature and classical tuong opera, notably plays portraying Xiang Yu's farewell to Consort Yu. Vietnamese chroniclers from Le Van Huu to Ngo Si Lien also absorbed Sima Qian's nuanced character judgment."
