      "vietnamReceptionVi": "Thành ngữ Đào lý bất ngôn, hạ tự thành hề được giới nhà nho và giáo dục Việt Nam trích dẫn rộng rãi để ca ngợi những bậc thầy và danh tướng sống thanh bạch, hữu xạ tự nhiên hương. Hình tượng Lý Quảng trung dũng mà long đong cũng đi vào nhiều bài thơ vịnh sử thời Lê – Nguyễn.",
      "vietnamReceptionEn": "The proverb about silent peach and plum trees forming paths beneath them became a favorite Vietnamese tribute to modest teachers and upright officials whose merit spoke for itself. Li Guang's loyal yet star-crossed career also inspired historical reflection poems in Le-Nguyen literature."
