      "vietnamReceptionVi": "Tư tưởng Nguyên Đạo xem văn chương là sự nối dài của Đạo vũ trụ được các nhà lý luận và biên tuyển văn học Việt Nam như Lê Quý Đôn, Ngô Thì Nhậm và Phan Huy Chú tiếp thu sâu sắc. Khái niệm văn dĩ tải đạo cùng bút pháp biền ngẫu chuẩn mực từ Văn Tâm Điêu Long ảnh hưởng trực tiếp tới thể chế chiếu, biểu và phú khoa cử Đại Việt.",
      "vietnamReceptionEn": "Liu Xie's thesis that literature extends cosmic pattern deeply influenced Vietnamese critics and anthologists such as Le Quy Don, Ngo Thi Nham, and Phan Huy Chu. Its harmony of moral substance and parallel-prose craft shaped imperial edicts, memorials, and examination rhapsodies in Dai Viet."
