      "vietnamReceptionVi": "Tục Khúc thủy lưu thương và thẩm mỹ thư pháp hành thư của Lan Đình Tập Tự tạo dấu ấn sâu đậm trong sinh hoạt tao đàn của văn nhân Việt Nam thời Lê – Nguyễn. Tao đàn Nhị Thập Bát Tú thời Lê Thánh Tông cùng giới thư pháp Hán Nôm nhiều đời đều lấy bút pháp Vương Hy Chi làm chuẩn mực rèn nét.",
      "vietnamReceptionEn": "The floating-cup poetry gathering and running-script elegance of the Orchid Pavilion Preface inspired Vietnamese literati circles across the Le and Nguyen dynasties. Both Le Thanh Tong's literary society and generations of Han-Nom calligraphers revered Wang Xizhi's brushwork as a stylistic benchmark."
