      "vietnamReceptionVi": "Hình ảnh Xuất ứ nê nhi bất nhiễm trong Ái Liên Thuyết gặp gỡ kỳ diệu với biểu tượng hoa sen bản địa trong ca dao Việt Nam (Gần bùn mà chẳng hôi tanh mùi bùn) và mỹ học Phật giáo Việt Nam. Mạc Đĩnh Chi thời Trần từng viết Ngọc Tỉnh Liên Phú nối tiếp trực tiếp cảm hứng quân tử thanh bạch này.",
      "vietnamReceptionEn": "Zhou Dunyi's motif of the lotus rising unstained from mud converged naturally with Vietnam's own folk verses on lotus purity and Buddhist aesthetics. Tran dynasty laureate Mac Dinh Chi directly echoed this gentleman-flower ideal in his celebrated Jade-Well Lotus Rhapsody."
