      "vietnamReceptionVi": "Tương Tiến Tửu truyền cảm hứng mạnh mẽ cho dòng thơ hát nói phóng khoáng của văn học Việt Nam thế kỷ XIX, đặc biệt qua sáng tác của Nguyễn Công Trứ và Cao Bá Quát. Câu Thiên sinh ngã tài tất hữu dụng trở thành lời tự khẳng định bản lĩnh quen thuộc của các thế hệ trí thức và người trẻ Việt Nam.",
      "vietnamReceptionEn": "Bring in the Wine energized nineteenth-century Vietnamese ca tru lyricism, notably the bold, free-spirited verse of Nguyen Cong Tru and Cao Ba Quat. Its declaration that heaven created one's talents for a purpose remains a widely quoted affirmation of self-belief in Vietnam."
