      "classicalFormula": "若 + Điều kiện，則... | A + 若 + B (giống như) | 若輩 / 若屬 (bọn ngươi)",
      "exampleZh": "海內存知己，天涯若比鄰。（王勃《送杜少府之任蜀州》）",
      "examplePinyin": "Hǎi nèi cún zhī jǐ, tiān yá ruò bǐ lín. (Wáng Bó, Sòng Dù Shàofǔ Zhī Rèn Shǔzhōu)",
      "exampleHanViet": "Hải nội tồn tri kỷ, thiên nhai nhược tỉ lân. (Vương Bột - Tống Đỗ Thiếu Phủ Chi Nhậm Thục Châu)",
      "exampleTransVi": "Trong bốn bể còn có người tri kỷ, thì nơi chân trời cũng tựa như hàng xóm láng giềng.",
      "exampleTransEn": "So long as a true confidant lives within the four seas, the ends of the earth feel like next-door neighbors. (Wang Bo, Seeing Off Sub-Prefect Du)",
      "contrastModernChineseVi": "Hiện đại vẫn giữ 若 trong văn viết với nghĩa 'nếu' và 'như' (若是, 宛若), nhưng nghĩa đại từ ngôi hai 'ngươi' (tương đương 你, như 若入前為壽) hoàn toàn xa lạ với tiếng Trung hiện đại và rất dễ dịch sai.",
      "contrastModernChineseEn": "Modern Chinese retains literary 若 for 'if' and 'like,' yet its classical second-person pronoun use ('you'—as in ruo ru qian wei shou) is obsolete and frequently misread."
