      "exampleTransVi": "Làm người ai chẳng có lỗi? Có lỗi mà biết sửa, không có điều thiện nào lớn hơn thế.",
      "exampleTransEn": "Who among mortals is without fault? To err and be able to reform—no goodness is greater than that. (Zuo Zhuan, Duke Xuan Year 2)",
