      "contrastModernChineseEn": "Modern Chinese mostly associates 莫 with 'do not' or fixed idioms; in Pre-Qin and Han prose, 莫 is primarily the negative subject pronoun 'no one/nothing,' often forming superlatives with 焉 or 於."
