        "1. The most widespread full passive construction from late Warring States through Han and Tang prose: 為 (read wéi) introduces the agent and 所 precedes the verb.",
        "2. The agent may be omitted in the contracted form 為所 + V ('to be V-ed').",
        "3. Also appears without 所 as 為 + Agent + V (e.g., 為天下笑, 'laughed at by the realm')."
