      "exampleZh": "不者，若屬皆且為所虜！（司馬遷《史記·項羽本紀》） / 衛太子為江充所敗。（《漢書·霍光傳》）",
      "examplePinyin": "Wèi Tàizǐ wéi Jiāng Chōng suǒ bài. (Hànshū · Huò Guāng Zhuàn)",
